import axios from "axios";
import MaterialTable from "material-table";
import React, { Component } from "react";

import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";

class Items extends Component {
  state = {
    rowData: [],
    tableLoaded: true
  };

  componentDidMount() {
    this.retrieveFromDb();
  }

  retrieveFromDb = () => {
    this.setState(state => ({
      tableLoaded: false,
      rowData: state.rowData
    }));
    axios
      .get("/api/changetracking")
      .then(res => {
        var rowData = res.data.map((x, index) => {
          return {
            user: x.updatedBy.name,
            updatedItem: x.updatedObject,
            type: x.updateType,
            client: x.client,
            model: x.model,
            time: x.date,
            update: x.update

            /*{ title: "Changed By", field: "user" },
            { title: "Updated Item Id", field: "updateItem" },
            { title: "Change Type", field: "type" },
            { title: "Client", field: "client" },
            { title: "Database", field: "model" },
            { title: "Change Date/Time", field: "time" }*/
          };
        });
        console.log(res.data);

        this.setState(state => ({
          tableLoaded: true,
          rowData
        }));
      })
      .catch(err => console.log(err));
  };
  render() {
    return (
      <div>
        <MaterialTable
          columns={[
            { title: "Changed By", field: "user" },
            { title: "Client", field: "client" },
            { title: "Database", field: "model" },
            { title: "Change Type", field: "type" },
            { title: "Updated Item Id", field: "updatedItem" },
            { title: "Change Date/Time", field: "time" }
          ]}
          data={this.state.rowData}
          title="Configuration History"
          detailPanel={rowData => {
            return (
              <iframe
                width="100%"
                height="315"
                src="https://www.youtube.com/embed/C0DPdy98e4c"
                frameborder="0"
                allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
                allowfullscreen
              />
            );
          }}
          onRowClick={(event, rowData, togglePanel) => togglePanel()}
        />
      </div>
    );
  }
}
export default Items;
